/// @file titan/generated/gamevals/types.h
/// @brief Native gameval POD metadata generated by SoxClientGhidraUpdater.
#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <span>
#include <string_view>

namespace titan::gamevals {

struct Entry {
    int32_t id;
    std::string_view constantName;
    std::string_view name;
    std::string_view sourceCatalog;
};

struct QuestEntry {
    int32_t rowId;
    int32_t questId;
    std::string_view constantName;
    std::string_view name;
    std::string_view sortName;
    std::string_view description;
    std::string_view sourceCatalog;
};

struct InterfaceComponentEntry {
    int32_t packedId;
    int32_t groupId;
    int32_t childId;
    std::string_view groupClassName;
    std::string_view constantName;
};

inline const Entry* findById(std::span<const Entry> entries, int32_t id) {
    for (const Entry& entry : entries) {
        if (entry.id == id) return &entry;
    }
    return nullptr;
}

inline const QuestEntry* findQuestByQuestId(std::span<const QuestEntry> entries,
                                             int32_t questId) {
    for (const QuestEntry& entry : entries) {
        if (entry.questId == questId) return &entry;
    }
    return nullptr;
}

inline const QuestEntry* findQuestByRowId(std::span<const QuestEntry> entries,
                                           int32_t rowId) {
    for (const QuestEntry& entry : entries) {
        if (entry.rowId == rowId) return &entry;
    }
    return nullptr;
}

inline const InterfaceComponentEntry* findInterfaceComponentByPackedId(
        std::span<const InterfaceComponentEntry> entries,
        int32_t packedId) {
    std::size_t left = 0;
    std::size_t right = entries.size();
    while (left < right) {
        const std::size_t mid = left + ((right - left) / 2);
        if (entries[mid].packedId < packedId) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left < entries.size() && entries[left].packedId == packedId
            ? &entries[left]
            : nullptr;
}

}  // namespace titan::gamevals
